def catalog_choices_2026():
    choices = []
    for category, brand, items in CATALOG_2026:
        for item in items:
            key = f"2026::{category}::{brand}::{item}"
            label = f"{category} → {brand} → {item}"
            choices.append((key, label))
    return tuple(choices)


def catalog_item_2026(key):
    if not key or not str(key).startswith("2026::"):
        return None
    parts = str(key).split("::", 3)
    if len(parts) != 4:
        return None
    _, category, brand, name = parts
    for cat, br, items in CATALOG_2026:
        if cat == category and br == brand and name in items:
            return {"key": key, "category": category, "brand": brand, "name": name}
    return None
